def solve(nums):
    # longest increasing subsequence length (strictly increasing)
    import bisect
    tails = []
    for x in nums:
        # find position to insert x in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

