def solve(nums):
    """Return length of longest strictly increasing subsequence in nums.
    Uses patience sorting with binary search (O(n log n)).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # Find insertion point (leftmost) to keep tails increasing
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

