def solve(matrix):
    if not matrix:
        return []
    # Determine dimensions, handle ragged rows by treating missing as end
    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, max(len(row) for row in matrix) - 1
    while top <= bottom and left <= right:
        # top row
        for col in range(left, right+1):
            if col < len(matrix[top]):
                result.append(matrix[top][col])
        top += 1
        # right column
        for row in range(top, bottom+1):
            if right < len(matrix[row]):
                result.append(matrix[row][right])
        right -= 1
        if top <= bottom:
            # bottom row
            for col in range(right, left-1, -1):
                if col < len(matrix[bottom]):
                    result.append(matrix[bottom][col])
            bottom -= 1
        if left <= right:
            # left column
            for row in range(bottom, top-1, -1):
                if left < len(matrix[row]):
                    result.append(matrix[row][left])
            left += 1
    return result

